 updateHockey(dt){const s=this.state,p=s.puck,m=s.mallet,W=this.W,H=this.H;p.x+=p.vx*dt;p.y+=p.vy*dt;if(p.x<p.r||p.x>W-p.r)p.vx*=-1;if(p.y<H*.09)p.vy=Math.abs(p.vy);if(Math.hypot(p.x-m.x,p.y-m.y)<p.r+m.r){let dx=p.x-m.x,dy=p.y-m.y,dd=Math.hypot(dx,dy)||1;p.vx=dx/dd*300+(dx*2);p.vy=-Math.abs(dy/dd*340)-80;this.addScore(1,p.x,p.y)}if(p.y<H*.13&&Math.abs(p.x-W/2)<W*.16){s.goals++;this.addScore(30,p.x,p.y);this.burst(p.x,p.y,'#8feaff',20);p.x=W/2;p.y=H*.42;p.vy=300;if(s.goals>=5)this.finish(true)}if(p.y>H+20){this.miss();p.x=W/2;p.y=H*.42;p.vy=-300}}
 kick(p){const s=this.state;const goal={x:this.W*.22,y:this.H*.12,w:this.W*.56,h:this.H*.2};const inside=p.x>goal.x&&p.x<goal.x+goal.w&&p.y>goal.y&&p.y<goal.y+goal.h;const blocked=Math.abs(p.x-s.goalieX)<this.W*.105;const success=inside&&!blocked;if(success){s.goals++;this.addScore(20,p.x,p.y);this.burst(p.x,p.y,'#ffe16c',16)}else{this.combo=0;this.miss();this.cb.onMessage?.(inside?'守门员扑到了！换个位置再射！':'球踢偏了！瞄准球门内！')}s.shots++;if(s.shots>=7){this.finish(s.goals>=4)}else{s.goalieX=rand(this.W*.34,this.W*.66)}}
 updateDino(dt){const s=this.state,p=s.player,H=this.H;s.run+=dt;s.spawn-=dt;if(s.spawn<=0){s.spawn=rand(.8,1.45);s.obstacles.push({x:this.W+40,y:H*.73,w:rand(25,45),h:rand(30,65),r:20,emoji:pick(['🌵','🪨','🪵'])})}p.vy+=1300*dt;p.y+=p.vy*dt;if(p.y>=H*.72){p.y=H*.72;p.vy=0;p.ground=true}for(let i=s.obstacles.length-1;i>=0;i--){const o=s.obstacles[i];o.x-=(320+this.elapsed*6)*dt;if(o.x<this.W*.24&&o.x+o.w>this.W*.18&&p.y>H*.72-o.h+15){if(!p.ground){this.addScore(1,o.x,o.y)}else{this.miss();o.x=-100}}if(o.x<-60){s.obstacles.splice(i,1);this.addScore(5,this.W*.3,H*.4)}}if(Math.floor(s.run)%8===0&&this.score>0){} }
 updateDodge(dt){const s=this.state;s.spawn-=dt;if(s.spawn<=0){s.spawn=rand(.28,.5);s.items.push({x:rand(30,this.W-30),y:-35,r:rand(15,28),vy:rand(180,300)+this.elapsed*3,bad:Math.random()<.85,emoji:Math.random()<.85?'☄️':'⭐'})}for(let i=s.items.length-1;i>=0;i--){const o=s.items[i];o.y+=o.vy*dt;if(Math.hypot(o.x-s.player.x,o.y-s.player.y)<o.r+s.player.r){s.items.splice(i,1);if(o.emoji==='⭐')this.addScore(15,o.x,o.y);else this.miss()}else if(o.y>this.H+50){s.items.splice(i,1)}}}
 updateFishing(dt){const s=this.state;for(const f of s.fish){f.x+=f.vx*dt;if(f.x<25||f.x>this.W-25)f.vx*=-1}const h=s.hook;if(h.drop){h.rope=Math.min(this.H*.54,h.rope+this.H*.65*dt);h.y=this.H*.26+h.rope;for(const f of s.fish){if(!f.caught&&Math.hypot(f.x-h.x,f.y-h.y)<f.r+15){f.caught=true;s.catches++;this.addScore(15,f.x,f.y);this.burst(f.x,f.y,'#7ceaff',10);h.drop=false;h.rope=0;this.setTimer(()=>{f.caught=false;f.x=rand(25,this.W-25);f.y=rand(this.H*.3,this.H*.68)},1200);break}}if(h.rope>=this.H*.54){h.drop=false;h.rope=0}}else{h.y=this.H*.26}}
 updateBubbleShoot(dt){const s=this.state;if(s.shot.active){const b=s.shot;b.x+=b.vx*dt;b.y+=b.vy*dt;if(b.x<20||b.x>this.W-20)b.vx*=-1;let hit=s.bubbles.find(o=>Math.hypot(o.x-b.x,o.y-b.y)<o.r+b.r);if(hit||b.y<this.H*.07){if(hit){const same=s.bubbles.filter(o=>o.c===b.c&&Math.hypot(o.x-hit.x,o.y-hit.y)<80);if(same.length>=2){for(const o of same){s.bubbles.splice(s.bubbles.indexOf(o),1);this.burst(o.x,o.y,['#ff698c','#ffd56a','#66e4ff','#91ffc6','#bc9bff'][o.c],9)}this.addScore(same.length*10,b.x,b.y)}else{s.bubbles.push({x:b.x,y:b.y,r:b.r,c:b.c})}}else s.bubbles.push({x:b.x,y:b.y,r:b.r,c:b.c});b.active=false;b.x=this.W/2;b.y=this.H*.84;b.vx=0;b.vy=0;b.c=ri(0,4);if(s.bubbles.length<8)this.finish(true)}}}
 updatePlane(dt){const s=this.state;s.spawn-=dt;if(s.spawn<=0){s.spawn=.6;s.items.push({x:this.W+30,y:rand(45,this.H-80),r:rand(16,33),vy:rand(-20,20),type:Math.random()<.33?'ring':'storm',color:pick(['#7deaff','#ffd46f','#a7a2ff'])})}for(let i=s.items.length-1;i>=0;i--){const o=s.items[i];o.x-=(280+this.elapsed*2)*dt;o.y+=o.vy*dt;if(Math.hypot(o.x-s.player.x,o.y-s.player.y)<o.r+s.player.r){s.items.splice(i,1);if(o.type==='ring'){this.addScore(12,o.x,o.y);this.burst(o.x,o.y,o.color,12)}else this.miss()}else if(o.x<-50)s.items.splice(i,1)}}
 updateRhythm(dt){const s=this.state;s.spawn-=dt;if(s.spawn<=0){s.spawn=.62;s.notes.push({lane:ri(0,2),y:-25,r:14})}for(let i=s.notes.length-1;i>=0;i--){s.notes[i].y+=this.H*.68*dt;if(s.notes[i].y>this.H*.94){s.notes.splice(i,1);this.combo=0}}if(this.elapsed>36)this.finish(true)}
 updateBoss(dt){const s=this.state,b=s.boss;b.phase+=dt;b.x=this.W/2+Math.sin(this.elapsed*1.2)*this.W*.28;b.weak=(Math.sin(b.phase*2.1)>0.6);s.spawn-=dt;if(s.spawn<=0){s.spawn=.42;s.bullets.push({x:b.x+rand(-70,70),y:this.H*.32,vy:rand(160,260),vx:rand(-60,60),r:rand(10,18)})}for(let i=s.bullets.length-1;i>=0;i--){const o=s.bullets[i];o.x+=o.vx*dt;o.y+=o.vy*dt;if(Math.hypot(o.x-s.player.x,o.y-s.player.y)<o.r+s.player.r){s.bullets.splice(i,1);this.miss()}else if(o.y>this.H+30)s.bullets.splice(i,1)}if(b.hp<=0)this.finish(true)}
 updatePinball(dt){const s=this.state,b=s.ball,W=this.W,H=this.H;b.x+=b.vx*dt;b.y+=b.vy*dt;b.vy+=290*dt;if(b.x<b.r||b.x>W-b.r)b.vx*=-1;if(b.y<b.r)b.vy=Math.abs(b.vy);for(const o of s.bumpers){if(Math.hypot(b.x-o.x,b.y-o.y)<b.r+o.r){const a=Math.atan2(b.y-o.y,b.x-o.x);b.vx=Math.cos(a)*320;b.vy=Math.sin(a)*320;this.addScore(5,o.x,o.y);o.hit=.2;this.burst(o.x,o.y,'#ffdc77',7)}}if(b.y>H-90&&b.y<H-45){const side=b.x<W*.5?0:1;if(Math.abs(s.paddles[side].ang)>0.3){b.vy=-Math.abs(b.vy)-160;b.vx+=(side===0?1:-1)*90;s.paddles[side].ang=0}}if(b.y>H+25){this.lives--;this.sound('hit');if(this.lives<=0)this.finish(this.score>=90);else{b.x=W/2;b.y=H*.66;b.vx=rand(-180,180);b.vy=-260}}}
 updateTraffic(dt){const s=this.state;s.spawn-=dt;if(s.spawn<=0){s.spawn=rand(.45,.75);const dir=ri(0,3),v=rand(100,170);s.cars.push({dir,x:dir===0?-30:dir===1?this.W+30:this.W/2+rand(-55,55),y:dir===2?-30:dir===3?this.H+30:this.H/2+rand(-55,55),v,color:pick(['#ff6f89','#79dfff','#ffce6f','#9dffc8']),r:18})}for(let i=s.cars.length-1;i>=0;i--){const c=s.cars[i],green=s.lights[c.dir];if(green){if(c.dir===0)c.x+=c.v*dt;if(c.dir===1)c.x-=c.v*dt;if(c.dir===2)c.y+=c.v*dt;if(c.dir===3)c.y-=c.v*dt}if(c.x>this.W+50||c.x<-50||c.y>this.H+50||c.y<-50){s.cars.splice(i,1);s.cleared++;this.addScore(5,this.W/2,this.H/2)}for(let j=i-1;j>=0;j--){const o=s.cars[j];if(Math.hypot(c.x-o.x,c.y-o.y)<c.r+o.r&&((c.dir%2)!==(o.dir%2))){s.cars.splice(i,1);s.cars.splice(j,1);this.miss();break}}}}
 floodFill(color){const s=this.state,old=s.grid[0][0];if(color===old)return;const st=[[0,0]],seen=new Set(['0,0']);while(st.length){const[x,y]=st.pop();if(s.grid[y]?.[x]!==old)continue;s.grid[y][x]=color;for(const[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy,k=`${nx},${ny}`;if(nx>=0&&ny>=0&&nx<s.cols&&ny<s.rows&&!seen.has(k)&&s.grid[ny][nx]===old){seen.add(k);st.push([nx,ny])}}}}
 isFloodWin(){const s=this.state,c=s.grid[0][0];return s.grid.every(row=>row.every(v=>v===c))}
 colorAt(p){const s=this.state,cols=6,w=56,gap=12,total=cols*w+(cols-1)*gap,x=(this.W-total)/2,y=this.H*.85;if(p.y<y-10||p.y>y+70)return -1;const c=Math.floor((p.x-x)/(w+gap));return c>=0&&c<6?c:-1}
