 moveFrog(i){const s=this.state,arr=s.frogs;if(!arr[i])return;const d=arr[i]==='L'?1:-1,j=i+d,k=i+2*d;if(arr[j]===''&&j>=0&&j<7){[arr[i],arr[j]]=[arr[j],arr[i]];this.addScore(2,this.W/2,this.H*.55);s.moves++;return}if(k>=0&&k<7&&arr[j]&&arr[j]!==arr[i]&&arr[k]===''){[arr[i],arr[k]]=[arr[k],arr[i]];this.addScore(3,this.W/2,this.H*.55);s.moves++}}
 laneAt(p){const s=this.state;return s.lanes.findIndex(x=>Math.abs(p.x-x)<this.W*.1)}
 draw(){const c=this.ctx,W=this.W,H=this.H;if(!c)return;c.setTransform(this.sx||1,0,0,this.sy||1,0,0);c.clearRect(0,0,W,H);const im=this.images[this.scene]||this.images.space;if(im&&im.complete&&im.naturalWidth){const ir=im.naturalWidth/im.naturalHeight,cr=W/H;let dw=W,dh=H,dx=0,dy=0;if(ir>cr){dh=H;dw=H*ir;dx=(W-dw)/2}else{dw=W;dh=W/ir;dy=(H-dh)/2}c.drawImage(im,dx,dy,dw,dh)}else{const g=c.createLinearGradient(0,0,W,H);g.addColorStop(0,'#123461');g.addColorStop(1,'#070d24');c.fillStyle=g;c.fillRect(0,0,W,H)}c.fillStyle='rgba(3,10,27,.65)';c.fillRect(0,0,W,H);const bg=c.createRadialGradient(W*.5,H*.45,20,W*.5,H*.45,W*.68);bg.addColorStop(0,'rgba(44,132,196,.15)');bg.addColorStop(1,'rgba(1,6,19,.48)');c.fillStyle=bg;c.fillRect(0,0,W,H);if(this.shake>0){c.save();c.translate(rand(-8,8),rand(-4,4))}this.drawGame(c);this.drawParticles(c);if(this.shake>0)c.restore()}
