 drawGame(c){const id=this.id,s=this.state,W=this.W,H=this.H;switch(id){
 case'meteor':case'bubble':case'whack':case'balloon':this.drawTap(c);break;case'fruit':this.drawFruit(c);break;case'brick':this.drawBrick(c);break;case'shooter':this.drawShooter(c);break;case'stack':this.drawStack(c);break;case'catch':this.drawCatch(c);break;case'laser':this.drawLaser(c);break;case'candy':this.drawCandy(c);break;case'sort':this.drawSort(c);break;case'slide':this.drawSlide(c);break;case'maze':this.drawMaze(c);break;case'memory':this.drawMemory(c);break;case'simon':this.drawSimon(c);break;case'cannon':this.drawCannon(c);break;case'hockey':this.drawHockey(c);break;case'penalty':this.drawPenalty(c);break;case'dino':this.drawDino(c);break;case'dodge':this.drawDodge(c);break;case'fishing':this.drawFishing(c);break;case'bubbleShoot':this.drawBubbleShoot(c);break;case'plane':this.drawPlane(c);break;case'dig':this.drawDig(c);break;case'flood':this.drawFlood(c);break;case'frog':this.drawFrog(c);break;case'rhythm':this.drawRhythm(c);break;case'boss':this.drawBoss(c);break;case'pinball':this.drawPinball(c);break;case'traffic':this.drawTraffic(c);break;case'splash':this.drawSplash(c);break;
 }}
 drawTap(c){const s=this.state,id=this.id,W=this.W,H=this.H;if(id==='whack'){const y0=H*.36;for(let r=0;r<3;r++)for(let col=0;col<3;col++){const x=W*(.25+col*.25),y=y0+r*H*.18;this.circle(c,x,y,46,'#10223d','#9fdcff55');c.fillStyle='#050b18';c.beginPath();c.ellipse(x,y+8,33,22,0,0,TAU);c.fill()}for(const o of s.items){this.drawText(c,o.emoji,o.x,o.y,42,o.bad?'#ff8ca1':'#fff')}this.drawText(c,'敲中怪兽 · 躲开捣蛋家伙',W/2,H*.16,25,'#e8f7ff');return}for(const o of s.items){if(id==='meteor'){this.circle(c,o.x,o.y,o.r,o.bad?'#67d7ff':o.color);this.drawText(c,o.bad?'🛸':o.emoji,o.x,o.y,Math.min(34,o.r*1.4),'#fff')}else if(id==='bubble'){c.save();const g=c.createRadialGradient(o.x-o.r*.3,o.y-o.r*.3,2,o.x,o.y,o.r);g.addColorStop(0,'#ffffffd9');g.addColorStop(.26,o.color);g.addColorStop(1,o.color+'33');c.fillStyle=g;c.beginPath();c.arc(o.x,o.y,o.r,0,TAU);c.fill();c.strokeStyle='#ffffff88';c.lineWidth=2;c.stroke();c.restore();if(o.bad)this.drawText(c,'✹',o.x,o.y,23,'#fff')}else{this.drawText(c,o.emoji||'🎈',o.x,o.y,o.r*1.7,o.color)}}this.drawText(c,`连击 COMBO ×${this.combo}`,W/2,H*.14,21,this.combo>=5?'#ffe28a':'#e5f6ff')}
 drawFruit(c){const s=this.state,W=this.W,H=this.H;c.fillStyle='#142b42';c.fillRect(0,H*.84,W,H*.16);for(const o of s.items)this.drawText(c,o.bad?'💣':o.emoji,o.x,o.y,o.r*1.9,o.color);for(let i=0;i<this.trail.length;i++){const p=this.trail[i];c.globalAlpha=p.life/.35;c.fillStyle='#8ffaff';c.beginPath();c.arc(p.x,p.y,5+(1-p.life/.35)*12,0,TAU);c.fill()}c.globalAlpha=1;this.drawText(c,'划动手指切水果！避开炸弹！',W/2,H*.13,23,'#fff')}
